package com.cowave.search.outbound_adapter.proxy

import com.cowave.search.client.proxy_api.ProxyApiClient
import com.cowave.search.domain.proxy.category.Category
import com.cowave.search.domain.proxy.category.CategoryRepository
import org.springframework.stereotype.Component

@Component
class CategoryRepositoryImpl(
    private val client: ProxyApiClient,
) : CategoryRepository {
    override fun findAllByIds(categoryIds: List<Int>): List<Category> {
        val query =
            """
            query GetCategories(${'$'}ids: [Int!]!) {
                categories(input: { ids: ${'$'}ids }) {
                    items {
                        id
                        name
                        depth
                        idPath
                        namePath
                        status
                    }
                }
            }
            """.trimIndent()

        return client.query(
            query = query,
            variables = mapOf("ids" to categoryIds),
            retrievePath = "categories.items",
            Category::class.java,
        )
    }
}

